import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const wall = new THREE.Group();

  const TILE_WIDTH = 1.0;
  const TILE_HEIGHT = 0.62;
  const GAP = 0.25;
  const GRID_COLS = 3;
  const GRID_ROWS = 2;
  const GRID_WIDTH = GRID_COLS * TILE_WIDTH + (GRID_COLS - 1) * GAP;
  const GRID_HEIGHT = GRID_ROWS * TILE_HEIGHT + (GRID_ROWS - 1) * GAP;

  const TEXT_COLOR = '#e8ecf2';
  const brands = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES'
  ];

  // Create vertical gradient texture
  const createGradientDataTexture = () => {
    const size = 256;
    const data = new Uint8Array(size * size * 4);
    const colorStart = new THREE.Color('#1a1a22');
    const colorEnd = new THREE.Color('#121218');

    for (let y = 0; y < size; y++) {
      const t = y / (size - 1);
      const color = new THREE.Color().lerpColors(colorStart, colorEnd, t);
      const r = Math.round(color.r * 255);
      const g = Math.round(color.g * 255);
      const b = Math.round(color.b * 255);

      for (let x = 0; x < size; x++) {
        const idx = (y * size + x) * 4;
        data[idx] = r;
        data[idx + 1] = g;
        data[idx + 2] = b;
        data[idx + 3] = 255;
      }
    }

    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    texture.needsUpdate = true;
    return texture;
  };

  const gradientTexture = createGradientDataTexture();

  // Kicker text
  const kickerText = ctx.fontAtlas.renderText('AS FEATURED IN', {
    fontSize: 9,
    fontWeight: 700,
    fontFamily: 'JetBrains Mono',
    color: TEXT_COLOR,
    opacity: 0.78
  });
  kickerText.position.y = GRID_HEIGHT / 2 + 0.3;
  wall.add(kickerText);

  const tiles = [];
  const timelines = [];
  let tileIndex = 0;

  for (let row = 0; row < GRID_ROWS; row++) {
    for (let col = 0; col < GRID_COLS; col++) {
      const x = -GRID_WIDTH / 2 + col * (TILE_WIDTH + GAP) + TILE_WIDTH / 2;
      const y = GRID_HEIGHT / 2 - row * (TILE_HEIGHT + GAP) - TILE_HEIGHT / 2;

      const geometry = new THREE.PlaneGeometry(TILE_WIDTH, TILE_HEIGHT);

      const material = new THREE.MeshStandardMaterial({
        map: gradientTexture,
        metalness: 0.5,
        roughness: 0.55,
        clearcoat: 0.2,
        clearcoatRoughness: 0.3,
        anisotropy: 0.6
      });

      const tile = new THREE.Mesh(geometry, material);

      const tileGroup = new THREE.Group();
      tileGroup.position.set(x, y, 0);
      tileGroup.add(tile);

      const brandText = ctx.fontAtlas.renderText(brands[tileIndex], {
        fontSize: 13,
        fontWeight: 700,
        fontFamily: 'JetBrains Mono',
        color: TEXT_COLOR,
        opacity: 0.78
      });
      brandText.position.z = 0.01;
      tileGroup.add(brandText);

      tileGroup.userData.brandText = brandText;
      tileGroup.userData.tile = tile;

      const onPointerOver = () => {
        gsap.to(tileGroup.position, {
          z: 0.05,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        if (brandText.material && 'opacity' in brandText.material) {
          gsap.to(brandText.material, {
            opacity: 1.0,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
        }
      };

      const onPointerOut = () => {
        gsap.to(tileGroup.position, {
          z: 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        if (brandText.material && 'opacity' in brandText.material) {
          gsap.to(brandText.material, {
            opacity: 0.78,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
        }
      };

      tileGroup.userData.handlers = {
        onPointerOver,
        onPointerOut
      };

      wall.add(tileGroup);
      tiles.push(tileGroup);
      tileIndex++;
    }
  }

  // Stagger mount animation
  const timeline = gsap.timeline();
  tiles.forEach((tileGroup, index) => {
    const startY = tileGroup.position.y;
    tileGroup.position.y = startY + 0.2;

    timeline.fromTo(
      tileGroup,
      { opacity: 0 },
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      index * 0.08
    );

    timeline.to(
      tileGroup.position,
      {
        y: startY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      index * 0.08
    );
  });
  timelines.push(timeline);

  // Key light at 35° elevation
  const elevation = (35 * Math.PI) / 180;
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(
    5 * Math.cos(elevation),
    5 * Math.sin(elevation),
    0
  );
  wall.add(keyLight);

  wall.userData.cleanup = () => {
    tiles.forEach(tileGroup => {
      const tile = tileGroup.userData.tile;
      if (tile && tile.geometry) tile.geometry.dispose();
      if (tile && tile.material) tile.material.dispose();
    });
    if (gradientTexture) gradientTexture.dispose();
    timelines.forEach(tl => tl.kill());
  };

  return wall;
}
